let activeMenu=null;function closeTableContextMenu(){if(activeMenu){activeMenu.cleanup();activeMenu=null}}function buildDeleteItem(e,t,n,o){if(e==="column"){return{label:__("Delete column"),run:()=>o.commands.deleteColumnAt(t,n)}}if(e==="row"){return{label:__("Delete row"),run:()=>o.commands.deleteRowAt(t,n)}}return{label:__("Delete table"),run:()=>o.commands.deleteTableAt(t)}}function positionTableMenu(e,t,n){const o=6;const l=e.offsetWidth;const a=e.offsetHeight;let s;let i;if(n==="row"){s=t.left-l-o;i=t.top+t.height/2-a/2}else if(n==="table"){s=t.left-l-16;i=t.top-a-16}else{s=t.left+t.width/2-l/2;i=t.top-a-o}s=Math.min(Math.max(8,s),window.innerWidth-l-8);i=Math.min(Math.max(8,i),window.innerHeight-a-8);e.style.left=`${s}px`;e.style.top=`${i}px`}function openTableContextMenu({anchorRect:e,kind:t,tablePos:n,index:o,editor:l}){closeTableContextMenu();const a=buildDeleteItem(t,n,o,l);const s=document.createElement("div");s.className="kb-table-menu";s.style.position="fixed";s.style.zIndex="1080";const i=document.createElement("button");i.type="button";i.className="kb-table-delete";i.setAttribute("aria-label",a.label);i.setAttribute("title",a.label);i.addEventListener("click",()=>{a.run();closeTableContextMenu();l.commands.focus()});s.appendChild(i);document.body.appendChild(s);const u=l.view?.dom;u?.classList.add("kb-table-menu-open");positionTableMenu(s,e,t);i.focus();const c=e=>{if(!s.contains(e.target)){closeTableContextMenu()}};const d=e=>{if(e.key==="Escape"){closeTableContextMenu();l.commands.focus()}};const r=()=>closeTableContextMenu();setTimeout(()=>{document.addEventListener("mousedown",c,true);document.addEventListener("keydown",d,true);window.addEventListener("scroll",r,true)},0);activeMenu={cleanup:()=>{document.removeEventListener("mousedown",c,true);document.removeEventListener("keydown",d,true);window.removeEventListener("scroll",r,true);u?.classList.remove("kb-table-menu-open");s.remove()}}}export{openTableContextMenu,closeTableContextMenu};